arguments.command:
cd /filesystem/Standards && python3 - <<'EOF'
import openpyxl
for f in ["CEL-2025-Q2_Certified_Equipment_List.xlsx","Superseded/CEL-2024-Q4_Certified_Equipment_List.xlsx"]:
    print("="*30, f)
    wb = openpyxl.load_workbook(f)
    print("props:", wb.properties.title, wb.properties.creator, wb.properties.created, wb.properties.modified, wb.properties.description, wb.properties.subject, wb.properties.keywords)
    for ws in wb.worksheets:
        print("--- sheet:", ws.title, ws.dimensions, "state:", ws.sheet_state)
        for row in ws.iter_rows():
            vals = [(c.coordinate, c.value) for c in row if c.value is not None]
            if vals: print(vals)
        # comments
        for row in ws.iter_rows():
            for c in row:
                if c.comment: print("COMMENT", c.coordinate, c.comment.text)
    print("defined names:", list(wb.defined_names.keys()) if hasattr(wb.defined_names,'keys') else wb.defined_names)
EOF

