import os, subprocess, openpyxl, docx, email
from email import policy
root="/filesystem"
for dp, dn, fns in os.walk(root):
    for fn in fns:
        p=os.path.join(dp,fn)
        rel=os.path.relpath(p,root).replace('/','__')
        out=os.path.join('fs',rel+'.txt')
        try:
            if fn.endswith('.pdf'):
                t=subprocess.run(['pdftotext','-layout',p,'-'],capture_output=True,text=True).stdout
            elif fn.endswith('.docx'):
                d=docx.Document(p)
                parts=[]
                for block in d.element.body.iterchildren():
                    tag=block.tag.split('}')[1]
                    if tag=='p':
                        parts.append(''.join(n.text or '' for n in block.iter() if n.tag.endswith('}t')))
                    elif tag=='tbl':
                        for row in block.iter():
                            if row.tag.endswith('}tr'):
                                cells=[]
                                for c in row:
                                    if c.tag.endswith('}tc'):
                                        cells.append(''.join(n.text or '' for n in c.iter() if n.tag.endswith('}t')))
                                parts.append(' | '.join(cells))
                t='\n'.join(parts)
                # headers/footers
                for s in d.sections:
                    for hp in s.header.paragraphs: t = "[HEADER] "+hp.text+"\n"+t
                    for fp in s.footer.paragraphs: t = t+"\n[FOOTER] "+fp.text
            elif fn.endswith('.xlsx'):
                wb=openpyxl.load_workbook(p)
                parts=[]
                for ws in wb.worksheets:
                    parts.append(f"### SHEET {ws.title} ({ws.sheet_state}) {ws.dimensions}")
                    for row in ws.iter_rows():
                        vals=[str(c.value) if c.value is not None else '' for c in row]
                        if any(vals): parts.append(' | '.join(vals))
                        for c in row:
                            if c.comment: parts.append(f"  [COMMENT {c.coordinate}] {c.comment.text}")
                t='\n'.join(parts)
            elif fn.endswith('.eml'):
                m=email.message_from_bytes(open(p,'rb').read(),policy=policy.default)
                hdr='\n'.join(f"{k}: {v}" for k,v in m.items())
                body=''
                for part in m.walk():
                    ct=part.get_content_type()
                    if ct in ('text/plain',):
                        body+=part.get_content()
                    elif part.get_filename():
                        body+=f"\n[ATTACHMENT {part.get_filename()} {ct}]\n"
                t=hdr+'\n\n'+body
            else:
                t=open(p,errors='replace').read()
        except Exception as e:
            t=f"ERROR {e}"
        open(out,'w').write(t)
        print(len(t), out)
